package org.example.spotifymixer.engine;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;import org.jf.dexlib2.immutable.*;import org.jf.dexlib2.immutable.instruction.*;import org.jf.dexlib2.dexbacked.*;import org.jf.dexlib2.writer.io.*;import org.jf.dexlib2.writer.pool.*;
public class MediaHookTest {
 @Test public void relocatesBothConstructorsAndPreservesSelfRegister()throws Exception{
  String name="Lp/bqf0;";List<Method> constructors=new ArrayList<>();for(List<String> params:Arrays.asList(Arrays.asList("Landroid/content/Context;","Ljava/lang/String;"),Collections.singletonList("Landroid/media/session/MediaSession;"))){List<ImmutableMethodParameter> args=new ArrayList<>();for(String p:params)args.add(new ImmutableMethodParameter(p,Collections.emptySet(),null));constructors.add(new ImmutableMethod(name,"<init>",args,"V",65537,Collections.emptySet(),Collections.emptySet(),new ImmutableMethodImplementation(10,Collections.singletonList(new ImmutableInstruction10x(Opcode.RETURN_VOID)),Collections.emptyList(),Collections.emptyList())));}
  Field f=new ImmutableField(name,"a","Landroid/media/session/MediaSession;",1,null,Collections.emptySet(),Collections.emptySet());ClassDef cls=new ImmutableClassDef(name,1,"Ljava/lang/Object;",Collections.emptyList(),null,Collections.emptySet(),Collections.singletonList(f),constructors);MemoryDataStore bytes=new MemoryDataStore();DexPool.writeTo(bytes,new ImmutableDexFile(Opcodes.forApi(24),Collections.singletonList(cls)));byte[][] out=MediaHook.patch(bytes.getData());assertTrue(new DexBackedDexFile(Opcodes.forApi(24),out[0]).getClasses().isEmpty());ClassDef result=new DexBackedDexFile(Opcodes.forApi(24),out[1]).getClasses().iterator().next();int count=0;for(Method m:result.getMethods()){Instruction call=m.getImplementation().getInstructions().iterator().next();assertEquals(Opcode.INVOKE_STATIC_RANGE,call.getOpcode());assertEquals(10-m.getParameterTypes().size()-1,((RegisterRangeInstruction)call).getStartRegister());assertEquals("capture",((MethodReference)((ReferenceInstruction)call).getReference()).getName());count++;}assertEquals(2,count);
 }
}
